        thread_tok.instance_id() == self.instance@.id(),
        thread_tok.value().pages.dom().contains(self.page_id()),
        thread_tok.value().pages[self.page_id()].num_blocks == 0,
        tok.instance_id() == self.instance@.id(),
        tok.key() == thread_tok.key(),
